        self.first = Node(start)
        self.item_count = 1

    def append(self, item):
        node = Node(item)
        cur = self.first
        while cur.next:
            cur = cur.next
        cur.next = node
        self.item_count += 1

    def remove(self, index):
        if index == 0:
            self.first = self.first.next
        else:
            cur = self.first
            for i in range(index - 1):
                cur = cur.next
            cur.next = cur.next.next
        self.item_count -= 1

    def get(self, index):
        cur = self.first
        for i in range(index):
            cur = cur.next
        return cur

